from pathlib import Path
p=Path('lib/main_online.dart')
s=p.read_text()
marker="""  String area(dynamic v) {\n    final x = safe(v).toLowerCase();\n    if (x == 'registro') return 'Registro';\n    const m = {\n      'managers': 'Usuários de gestão',\n      'drivers': 'Usuários operacionais',\n      'user_permissions': 'Permissões',\n      'role_default_permissions': 'Permissões padrão',\n      'works': 'Obras',\n      'companies': 'Empresas',\n      'receipt_lots': 'Notas fiscais / lotes',\n      'refinery_receipts': 'Recebimentos',\n      'machines': 'Ativos',\n      'third_party_vehicles': 'Equipamentos de terceiros'\n    };\n    return m[x] ?? safe(v);\n  }\n"""
insert="""  String area(dynamic v) {\n    final x = safe(v).toLowerCase();\n    if (x == 'registro') return 'Registro';\n    const m = {\n      'managers': 'Usuários de gestão',\n      'drivers': 'Usuários operacionais',\n      'user_permissions': 'Permissões',\n      'role_default_permissions': 'Permissões padrão',\n      'works': 'Obras',\n      'companies': 'Empresas',\n      'receipt_lots': 'Notas fiscais / lotes',\n      'refinery_receipts': 'Recebimentos',\n      'machines': 'Ativos',\n      'third_party_vehicles': 'Equipamentos de terceiros'\n    };\n    return m[x] ?? safe(v);\n  }\n\n  static const Set<String> _auditHiddenFieldsV102 = {\n    'id',\n    'device_id',\n    'session_id',\n    'client_event_id',\n    'event_id',\n    'event_uuid',\n    'state',\n    'platform',\n    'user_agent',\n    'ip_address',\n    'auth_user_id',\n    'manager_id',\n    'driver_id',\n    'created_by',\n    'updated_by',\n    'sync_status',\n    'synced_at',\n    'offline_id',\n    'local_id',\n    'request_id',\n    'trace_id',\n  };\n\n  dynamic _auditDecodeV102(dynamic raw) {\n    if (raw is String) {\n      final text = raw.trim();\n      if ((text.startsWith('{') && text.endsWith('}')) ||\n          (text.startsWith('[') && text.endsWith(']'))) {\n        try {\n          return jsonDecode(text);\n        } catch (_) {}\n      }\n    }\n    return raw;\n  }\n\n  String _auditFieldLabelV102(String raw) {\n    const labels = {\n      'name': 'Nome',\n      'username': 'Usuário',\n      'login': 'Login',\n      'role': 'Perfil',\n      'status': 'Situação',\n      'active': 'Ativo',\n      'enabled': 'Habilitado',\n      'code': 'Código',\n      'movement_code': 'Código do abastecimento',\n      'movement_type': 'Tipo de movimentação',\n      'tank_code': 'Comboio / unidade',\n      'tank_name': 'Nome do comboio / unidade',\n      'unit_code': 'Comboio / unidade',\n      'unit_name': 'Nome do comboio / unidade',\n      'invoice_number': 'NF',\n      'nf': 'NF',\n      'liters': 'Litros',\n      'volume_liters': 'Volume',\n      'quantity': 'Quantidade',\n      'price': 'Preço',\n      'unit_price': 'Preço unitário',\n      'purchase_price': 'Preço de compra',\n      'sale_price': 'Preço de venda',\n      'purchase_value': 'Valor de compra',\n      'sale_value': 'Valor de venda',\n      'difference_value': 'Diferença',\n      'work_name': 'Obra',\n      'work_code': 'Código da obra',\n      'company_name': 'Empresa',\n      'supplier_name': 'Fornecedor',\n      'plate': 'Placa',\n      'asset_number': 'Ativo',\n      'machine_code': 'Ativo',\n      'description': 'Descrição',\n      'reason': 'Motivo',\n      'notes': 'Observações',\n      'observation': 'Observação',\n      'permission': 'Permissão',\n      'permissions': 'Permissões',\n      'created_at': 'Data de criação',\n      'updated_at': 'Data da alteração',\n      'date': 'Data',\n      'operator_name': 'Operador',\n      'user_name': 'Usuário',\n    };\n    if (labels.containsKey(raw)) return labels[raw]!;\n    final words = raw\n        .replaceAll(RegExp(r'[_\\-]+'), ' ')\n        .trim()\n        .split(RegExp(r'\\s+'))\n        .where((x) => x.isNotEmpty)\n        .toList();\n    if (words.isEmpty) return raw;\n    final text = words.join(' ');\n    return text[0].toUpperCase() + text.substring(1);\n  }\n\n  String _auditValueV102(dynamic raw, {String? field}) {\n    final value = _auditDecodeV102(raw);\n    if (value == null) return '—';\n    if (value is bool) return value ? 'Sim' : 'Não';\n    if (value is num) {\n      if (field != null &&\n          (field.contains('price') || field.contains('value') || field.contains('cost'))) {\n        return _fmtMoney(value);\n      }\n      if (field != null &&\n          (field.contains('liter') || field.contains('volume'))) {\n        return _fmtLiters(value);\n      }\n      return '$value';\n    }\n    if (value is List) {\n      final readable = value\n          .map((x) => _auditValueV102(x))\n          .where((x) => x != '—' && x.trim().isNotEmpty)\n          .toList();\n      return readable.isEmpty ? '—' : readable.join(', ');\n    }\n    if (value is Map) {\n      final lines = _auditReadableLinesV102(value);\n      return lines.isEmpty ? '—' : lines.join(' | ');\n    }\n    final text = '$value'.trim();\n    if (text.isEmpty || text == 'undefined' || text == 'null') return '—';\n    final k = text.toLowerCase();\n    const translated = {\n      'active': 'Ativo',\n      'inactive': 'Inativo',\n      'enabled': 'Habilitado',\n      'disabled': 'Desabilitado',\n      'open': 'Aberto',\n      'closed': 'Encerrado',\n      'pending': 'Pendente',\n      'approved': 'Aprovado',\n      'rejected': 'Rejeitado',\n      'online': 'Online',\n      'offline': 'Offline',\n      'admin': 'Administrador',\n      'manager': 'Gerente',\n      'supervisor': 'Supervisor',\n      'operator': 'Operacional',\n      'fuel_driver': 'Operacional',\n      'fueling': 'Abastecimento',\n      'tank_transfer': 'Transferência',\n      'refinery_entry': 'Recebimento / NF',\n    };\n    if (translated.containsKey(k)) return translated[k]!;\n    final parsed = DateTime.tryParse(text);\n    if (parsed != null && (text.contains('T') || text.endsWith('Z'))) {\n      return _fmtDate(text);\n    }\n    return text;\n  }\n\n  List<String> _auditReadableLinesV102(dynamic raw) {\n    final decoded = _auditDecodeV102(raw);\n    if (decoded is! Map) return const <String>[];\n    final map = Map<String, dynamic>.from(decoded);\n    final lines = <String>[];\n    for (final entry in map.entries) {\n      final key = entry.key.trim();\n      final lower = key.toLowerCase();\n      if (key.isEmpty || _auditHiddenFieldsV102.contains(lower)) continue;\n      if (lower.endsWith('_id') || lower.endsWith('_uuid') || lower.endsWith('_token')) continue;\n      final value = _auditValueV102(entry.value, field: lower);\n      if (value == '—' || value.trim().isEmpty) continue;\n      lines.add('${_auditFieldLabelV102(lower)}: $value');\n    }\n    return lines;\n  }\n\n  Widget _auditDetailsV102(Map<String, dynamic> x, String user,\n      String detail, String table, String ref) {\n    final before = _auditReadableLinesV102(x['old_data']);\n    final after = _auditReadableLinesV102(x['new_data']);\n    final sections = <Widget>[\n      SelectableText(\n        'Data/hora: ${_fmtDate(x['created_at'])}\\n'\n        'Usuário: $user\\n'\n        'Registro: $detail\\n'\n        'Área: $table${ref == '—' ? '' : '\\nReferência: $ref'}',\n      ),\n    ];\n    if (before.isNotEmpty) {\n      sections.add(const SizedBox(height: 16));\n      sections.add(const Text('Antes da alteração',\n          style: TextStyle(fontWeight: FontWeight.w900)));\n      sections.add(const SizedBox(height: 6));\n      sections.add(SelectableText(before.join('\\n')));\n    }\n    if (after.isNotEmpty) {\n      sections.add(const SizedBox(height: 16));\n      sections.add(Text(before.isEmpty ? 'Informações do registro' : 'Depois da alteração',\n          style: const TextStyle(fontWeight: FontWeight.w900)));\n      sections.add(const SizedBox(height: 6));\n      sections.add(SelectableText(after.join('\\n')));\n    }\n    if (before.isEmpty && after.isEmpty) {\n      sections.add(const SizedBox(height: 16));\n      sections.add(const Text(\n        'Não há informações operacionais adicionais para exibir neste evento.',\n        style: TextStyle(color: Colors.black54),\n      ));\n    }\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: sections,\n    );\n  }\n"""
if marker not in s:
    raise SystemExit('area marker not found')
s=s.replace(marker,insert,1)
old="""                          content: SingleChildScrollView(\n                              child: SelectableText(\n                            'Data/hora: ${_fmtDate(x['created_at'])}\\nUsuário: $user\\nRegistro: $detail\\nÁrea: $table\\nReferência: $ref\\n\\nDados anteriores:\\n${const JsonEncoder.withIndent('  ').convert(x['old_data'])}\\n\\nDados do evento:\\n${const JsonEncoder.withIndent('  ').convert(x['new_data'])}',\n                          )),\n"""
new="""                          content: SingleChildScrollView(\n                            child: _auditDetailsV102(x, user, detail, table, ref),\n                          ),\n"""
if old not in s:
    raise SystemExit('dialog JSON block not found')
s=s.replace(old,new,1)
if "Text('v101'" not in s:
    raise SystemExit('v101 marker missing')
s=s.replace("Text('v101'", "Text('v102'", 1)
p.write_text(s)
print('patched', len(s))
